function Reveal({children,delay=0,style}){const{reducedMotion}=useResponsive();const value=useRef(new Animated.Value(0)).current;useEffect(()=>{if(reducedMotion){value.setValue(1);return}Animated.timing(value,{toValue:1,duration:420,delay,easing:Easing.out(Easing.cubic),useNativeDriver:true}).start()},[delay,reducedMotion,value]);return <Animated.View style={[style,{opacity:value,transform:[{translateY:value.interpolate({inputRange:[0,1],outputRange:[12,0]})}]}]}>{children}</Animated.View>}
function AppBackdrop(){return <View pointerEvents="none" style={StyleSheet.absoluteFill}><Svg width="100%" height="100%"><Defs><SvgLinearGradient id="surface" x1="0" y1="0" x2="1" y2="1"><Stop offset="0" stopColor="#130D10"/><Stop offset=".48" stopColor="#09090B"/><Stop offset="1" stopColor="#100C0F"/></SvgLinearGradient><RadialGradient id="halo"><Stop offset="0" stopColor="#FF3441" stopOpacity=".16"/><Stop offset="1" stopColor="#FF3441" stopOpacity="0"/></RadialGradient></Defs><Rect width="100%" height="100%" fill="url(#surface)"/><Circle cx="86%" cy="4%" r="360" fill="url(#halo)"/><Circle cx="8%" cy="94%" r="280" fill="url(#halo)" opacity=".35"/><Path d="M0 120 L1600 120 M0 360 L1600 360 M0 600 L1600 600 M260 0 L260 1000 M620 0 L620 1000 M980 0 L980 1000 M1340 0 L1340 1000" stroke="#FF6670" strokeOpacity=".025" strokeWidth="1"/></Svg></View>}
let activeVoiceOwner=null
function VoiceField({label,value,onChangeText,placeholder,disabled=false}){const{phone}=useResponsive();const owner=useRef(Symbol(label)),base=useRef(''),[listening,setListening]=useState(false),[error,setError]=useState('');useSpeechRecognitionEvent('start',()=>{if(activeVoiceOwner===owner.current)setListening(true)});useSpeechRecognitionEvent('end',()=>{if(activeVoiceOwner===owner.current){setListening(false);activeVoiceOwner=null}});useSpeechRecognitionEvent('result',event=>{if(activeVoiceOwner!==owner.current)return;const transcript=event.results?.[0]?.transcript||'';if(transcript)onChangeText(joinVoiceText(base.current,transcript))});useSpeechRecognitionEvent('error',event=>{if(activeVoiceOwner!==owner.current)return;setListening(false);setError(voiceErrorMessage(event.error));activeVoiceOwner=null});useEffect(()=>()=>{if(activeVoiceOwner===owner.current){ExpoSpeechRecognitionModule.abort();activeVoiceOwner=null}},[]);const toggle=async()=>{if(listening){ExpoSpeechRecognitionModule.stop();return}setError('');if(activeVoiceOwner)ExpoSpeechRecognitionModule.abort();const permission=await ExpoSpeechRecognitionModule.requestPermissionsAsync();if(!permission.granted){setError('Brak dostępu do mikrofonu.');return}if(!ExpoSpeechRecognitionModule.isRecognitionAvailable()){setError('Włącz usługę rozpoznawania mowy w ustawieniach Androida.');return}base.current=String(value||'');activeVoiceOwner=owner.current;ExpoSpeechRecognitionModule.start({lang:'pl-PL',interimResults:true,continuous:false,maxAlternatives:1})};return <View style={[s.field,phone&&rp.fieldPhone]}><Text style={s.label}>{label}</Text><View style={[ve.wrap,listening&&ve.wrapActive]}><TextInput editable={!disabled} style={[s.input,s.area,ve.input,disabled&&{opacity:.5}]} value={String(value??'')} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#776D72" multiline/><Pressable disabled={disabled} onPress={toggle} style={[ve.button,listening&&ve.buttonActive]}><Text style={ve.icon}>🎙</Text><Text style={ve.buttonText}>{listening?'SŁUCHAM':'DYKTUJ'}</Text></Pressable></View>{listening&&<Text style={ve.status}>● Mów po polsku. Zatrzymaj po zakończeniu.</Text>}{!!error&&<Text style={ve.error}>{error}</Text>}</View>}
function Field({label,value,onChangeText,placeholder,multiline=false,keyboardType,disabled=false,voice=false}){const{phone}=useResponsive();if(multiline&&voice)return <VoiceField label={label} value={value} onChangeText={onChangeText} placeholder={placeholder} disabled={disabled}/>;return <View style={[s.field,phone&&rp.fieldPhone]}><Text style={s.label}>{label}</Text><TextInput editable={!disabled} style={[s.input,multiline&&s.area,disabled&&{opacity:.5}]} value={String(value??'')} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#776D72" multiline={multiline} keyboardType={keyboardType}/></View>}
function SelectField({label,value,items,onChange,placeholder='— wybierz —',disabled=false,manualLabel='Inny / wpisz ręcznie…'}){const{phone}=useResponsive();const[open,setOpen]=useState(false),[query,setQuery]=useState('');const visible=filterRecords(items,query,item=>item);return <View style={[s.field,phone&&rp.fieldPhone]}><Text style={s.label}>{label}</Text><Pressable accessibilityRole="button" accessibilityState={{disabled}} disabled={disabled} onPress={()=>{setQuery('');setOpen(true)}} style={[s.input,s.selectBox,disabled&&{opacity:.5}]}><Text style={[s.selectText,!value&&{color:'#776D72'}]}>{value||placeholder}</Text><Text style={s.selectArrow}>▾</Text></Pressable><Modal visible={open} transparent animationType="fade" onRequestClose={()=>setOpen(false)}><KeyboardAvoidingView style={s.modalKeyboard} behavior={Platform.OS==='ios'?'padding':'height'}><Pressable style={[s.modalShade,phone&&rp.modalShadePhone]} onPress={()=>setOpen(false)}><Pressable style={[s.selectModal,phone&&rp.fullModalPhone]} onPress={()=>{}}><Text style={[s.panelTitle,{marginBottom:12}]}>{label}</Text><SearchBar value={query} onChange={setQuery} count={visible.length} placeholder="Szukaj na liście…"/><ScrollView keyboardShouldPersistTaps="handled" style={{maxHeight:480,borderWidth:1,borderColor:'#40343B',borderRadius:10,backgroundColor:'#181519'}}>{visible.map(x=><Pressable key={String(x)} style={s.selectItem} onPress={()=>{onChange(String(x));setOpen(false)}}><Text style={s.rowTitle}>{String(x)}</Text></Pressable>)}<Pressable style={s.selectItem} onPress={()=>{onChange('__manual__');setOpen(false)}}><Text style={s.warn}>{manualLabel}</Text></Pressable></ScrollView><Button onPress={()=>setOpen(false)}>Anuluj</Button></Pressable></Pressable></KeyboardAvoidingView></Modal></View>}
function PillRow({items,value,onChange}){return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.pills}>{items.map(x=><Pressable accessibilityRole="tab" accessibilityState={{selected:value===x}} key={x} onPress={()=>onChange(x)} android_ripple={{color:'#FF465122'}} style={[s.pill,value===x&&s.pillOn]}><Text style={[s.pillText,value===x&&{color:'#FFFFFF'}]}>{String(x).replaceAll('_',' ')}</Text></Pressable>)}</ScrollView>}
