function BootScreen(){const reveal=useRef(new Animated.Value(0)).current,pulse=useRef(new Animated.Value(0)).current;useEffect(()=>{Animated.parallel([Animated.timing(reveal,{toValue:1,duration:650,easing:Easing.out(Easing.cubic),useNativeDriver:true}),Animated.loop(Animated.sequence([Animated.timing(pulse,{toValue:1,duration:900,easing:Easing.inOut(Easing.quad),useNativeDriver:true}),Animated.timing(pulse,{toValue:0,duration:900,easing:Easing.inOut(Easing.quad),useNativeDriver:true})]))]).start()},[pulse,reveal]);return <SafeAreaView style={s.bootRoot}><Animated.View style={{opacity:reveal,transform:[{translateY:reveal.interpolate({inputRange:[0,1],outputRange:[12,0]})},{scale:pulse.interpolate({inputRange:[0,1],outputRange:[1,1.018]})}]}}><Image source={BRAND_LOGO} resizeMode="contain" style={s.bootLogo}/></Animated.View><View style={s.bootLoader}><ActivityIndicator color={theme.colors.primary} size="small"/><Text style={s.bootText}>URUCHAMIANIE SYSTEMU WARSZTATOWEGO</Text></View></SafeAreaView>}

export default function App(){
 const{width}=useWindowDimensions(); const mode=layoutMode(width),phone=mode==='phone',compact=mode!=='desktop',reducedMotion=useReducedMotion()
 const[ready,setReady]=useState(false),[page,setPage]=useState('dashboard'),[tick,setTick]=useState(0),[syncing,setSyncing]=useState(false),[lastSync,setLastSync]=useState(''),[selectedOrder,setSelectedOrder]=useState(''),[orderContext,setOrderContext]=useState(null),[deliveryScanner,setDeliveryScanner]=useState(false),[notices,setNotices]=useState([]),notice=notices[0]||null
 useEffect(()=>{Promise.all([initDb(),new Promise(resolve=>setTimeout(resolve,900))]).then(()=>setReady(true)).catch(e=>Alert.alert('Baza',e.message))},[])
 const refresh=()=>setTick(x=>x+1)
 const notify=useCallback((message,tone='success',title='Autologika')=>setNotices(queue=>[{message,tone,title,id:Date.now()+queue.length},...queue].slice(0,5)),[])
 const dismissNotice=useCallback(()=>setNotices(queue=>queue.slice(1)),[])
 const sync=async(silent=false,full=false)=>{setSyncing(true);try{const r=await syncNow({full});setLastSync(new Date().toLocaleTimeString('pl-PL'));refresh();if(!silent){const emptyHint=r.full&&r.remoteRows===0?' Chmura tego konta jest pusta — sprawdź konto na obu urządzeniach.':'';notify(`Wysłano: ${r.pushed}, pobrano: ${r.pulled}, konflikty: ${r.conflicts||0}, zdjęcia ↑ ${r.filesUp||0} / ↓ ${r.filesDown||0}.${emptyHint}`,'success','Synchronizacja zakończona')}}catch(e){if(!silent)notify(e.message,'danger','Błąd synchronizacji')}finally{setSyncing(false)}}
 useEffect(()=>{if(!ready)return;let alive=true;const boot=async()=>{const c=await loadCloud();if(c.autoSync&&alive)sync(true)};boot();const t=setInterval(async()=>{const c=await loadCloud();if(c.autoSync&&!syncing)sync(true)},30000);return()=>{alive=false;clearInterval(t)}},[ready])
 const updateSeen=useRef('')
 useEffect(()=>{
  if(!ready)return
  let live=true,lastCheck=0,checking=false
  const check=async()=>{if(checking||Date.now()-lastCheck<6*60*60*1000)return;checking=true;try{if(await metaGet('autoUpdateNotifications')==='0')return;const update=await fetchReleaseUpdate(Application.nativeApplicationVersion||APP_VERSION);lastCheck=Date.now();if(live&&update.available&&updateSeen.current!==update.version){updateSeen.current=update.version;Alert.alert('Nowa wersja Autologiki',`Dostępna jest wersja ${update.version}. Pobierzesz ją w Ustawieniach.`,[{text:'Później',style:'cancel'},{text:'Otwórz ustawienia',onPress:()=>setPage('settings')}])}}catch{}finally{checking=false}}
  check();const subscription=AppState.addEventListener('change',state=>{if(state==='active')check()})
  return()=>{live=false;subscription.remove()}
 },[ready])
 const navigate=id=>{if(id==='orderCenter'){setSelectedOrder('');setOrderContext(null)}setPage(id)}
 const openCenter=(id,context=null)=>{setSelectedOrder(id);setOrderContext(context);setPage('orderCenter')}
 if(!ready)return <BootScreen/>
 return <FeedbackContext.Provider value={notify}><ResponsiveContext.Provider value={{mode,phone,compact,reducedMotion}}><SafeAreaView style={s.root}><AppBackdrop/><View style={s.shell}>{!compact&&<Sidebar page={page} setPage={navigate} sync={sync} syncing={syncing} lastSync={lastSync}/>}<View style={s.main}><Header page={page} compact={compact} phone={phone} sync={sync} syncing={syncing}/><ScrollView contentContainerStyle={[s.content,compact&&s.contentCompact,phone&&rp.contentPhone]} showsVerticalScrollIndicator={false}><PageTransition key={page}>{page==='dashboard'&&<WorkshopDashboard tick={tick} openCenter={openCenter} navigate={navigate} phone={phone} scanDeliveryDocument={()=>setDeliveryScanner(true)}/>}{page==='intake'&&<Intake tick={tick} refresh={refresh} openCenter={openCenter}/>}{page==='workflow'&&<Workflow tick={tick} refresh={refresh} openCenter={openCenter}/>}{page==='schedule'&&<Schedule tick={tick} refresh={refresh} openCenter={openCenter}/>}{page==='orders'&&<Orders tick={tick} refresh={refresh} openCenter={openCenter}/>}{page==='orderCenter'&&<OrderCenter tick={tick} refresh={refresh} orderId={selectedOrder} setOrderId={setSelectedOrder} initialContext={orderContext}/>}{page==='customers'&&<CustomerRecords tick={tick} refresh={refresh} openCenter={openCenter}/>} {page==='vehicles'&&<VehicleRecords tick={tick} refresh={refresh} openCenter={openCenter}/>}{page==='repairBase'&&<RepairDatabase tick={tick} refresh={refresh}/>}{page==='parts'&&<Parts tick={tick} refresh={refresh} openCenter={openCenter} scanDeliveryDocument={()=>setDeliveryScanner(true)}/>}{page==='diagnostics'&&<Diagnostics tick={tick} refresh={refresh}/>}{page==='payments'&&<Payments tick={tick} refresh={refresh}/>}{page==='finance'&&<MobileFinance tick={tick} openCenter={openCenter}/>}{page==='documents'&&<Documents tick={tick}/>}{page==='settings'&&<Settings sync={sync} syncing={syncing}/>}</PageTransition></ScrollView>{compact&&<MobileNav page={page} setPage={navigate} phone={phone}/>}</View></View><DeliveryDocumentScanner visible={deliveryScanner} onClose={()=>setDeliveryScanner(false)} onImported={()=>{refresh();setPage('parts');notify('Pozycje z dokumentu dodano do magazynu.','success','Dostawa przyjęta')}}/><FeedbackToast notice={notice} onClose={dismissNotice}/></SafeAreaView></ResponsiveContext.Provider></FeedbackContext.Provider>
}
function Sidebar({page,setPage,sync,syncing,lastSync}){return <View style={s.sidebar}><View style={s.brand}><Image source={BRAND_LOGO} resizeMode="contain" style={s.sidebarLogo}/><View style={s.brandVersion}><View style={s.brandPulse}/><Text style={s.brandS}>ANDROID OS {Application.nativeApplicationVersion||APP_VERSION}</Text></View></View><ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={s.navList}>{NAV.map(([id,label])=><Pressable accessibilityRole="button" accessibilityState={{selected:page===id}} key={id} style={({pressed})=>[s.nav,page===id&&s.navOn,pressed&&s.navPressed]} onPress={()=>setPage(id)}><View style={[s.navIndicator,page===id&&s.navIndicatorOn]}/><MaterialCommunityIcons name={NAV_ICONS[id]} size={20} color={page===id?theme.colors.primary:'#8E858A'}/><Text style={[s.navTxt,page===id&&s.navTxtOn]}>{label}</Text></Pressable>)}</ScrollView><View style={s.syncBox}><View style={s.syncLabel}><View style={s.dot}/><Text style={s.localT}>OFFLINE-FIRST</Text></View><Button onPress={()=>sync(false)} disabled={syncing}>{syncing?'Synchronizuję…':'↻ Synchronizuj'}</Button>{!!lastSync&&<Text style={s.muted}>Ostatnia synchronizacja: {lastSync}</Text>}</View></View>}
