  const reset={}
  if(field==='make')Object.assign(reset,{model:'',generation:'',year:'',engine:'',power_hp:'',engine_code:''})
  if(field==='model')Object.assign(reset,{generation:'',year:'',engine:'',power_hp:'',engine_code:''})
  if(field==='generation')Object.assign(reset,{year:'',engine:'',power_hp:'',engine_code:''})
