 const o=orders.find(x=>sameRecordId(x.cloud_id,orderId)),p=o?.payload||{},vehicleRelation=resolveOrderVehicle(p,vehicles),car=vehicleRelation.display,vehicleId=vehicleRelation.vehicle?.cloud_id||p.vehicle_cloud_id;const vehicleOrders=orders.filter(x=>sameRecordId(x.payload.vehicle_cloud_id,vehicleId)),vehicleOrderIds=new Set(vehicleOrders.map(x=>recordId(x.cloud_id))),serviceOrders=attachServiceHistory(vehicleOrders.map(x=>({id:x.cloud_id,...x.payload})),allItems),health=buildVehicleHealth({vehicle:car,orders:serviceOrders,findings:healthFindings.filter(x=>sameRecordId(x.payload.vehicle_cloud_id,vehicleId)).map(x=>x.payload),reminders:healthReminders.filter(x=>sameRecordId(x.payload.vehicle_cloud_id,vehicleId)).map(x=>x.payload),diagnostics:allDiagnostics.filter(x=>vehicleOrderIds.has(recordId(x.payload.order_cloud_id))).map(x=>({order_id:x.payload.order_cloud_id,...x.payload}))});const paid=payments.reduce((a,x)=>a+Number(x.payload.amount||0),0),itemsTotal=items.reduce((a,x)=>a+Number(x.payload.qty||1)*Number(x.payload.unit_price||0),0),calculatedTotal=items.length?itemsTotal:Number(p.total||0),total=p.final_price===null||p.final_price===undefined?calculatedTotal:Number(p.final_price),due=Math.max(0,total-paid),partsOpen=parts.filter(x=>!['ZAMONTOWANE','ZWROT_ZAKONCZONY','ANULOWANE'].includes(x.payload.status)),matchingStock=matchingInventoryParts(inventory,car),matchingStockIds=new Set(matchingStock.map(row=>String(row.cloud_id))),repairItems=items.filter(item=>!['CZESC','PART'].includes(String(item.payload.kind||'').toUpperCase())),selectedRepair=repairItems.find(item=>sameRecordId(item.cloud_id,selectedRepairId)),availableStock=filterRecords(inventory.filter(row=>Number(row.payload.stock||0)>0),stockQuery),workflow=deriveMobileOrderWorkflow({order:p,diagnosis:diag?.payload||{},approvals,parts,items,logs,payments,qc,procedures,notes:notes?.payload||{},total})
 useEffect(()=>{if(!o||!sameRecordId(loadedOrderId,orderId)||p.status==='WYDANE')return;const current=statuses.indexOf(p.status||'PRZYJETE'),suggested=statuses.indexOf(workflow.suggestedStatus);if(suggested>current)patch('orders',orderId,{status:workflow.suggestedStatus}).then(refresh).catch(error=>Alert.alert('Status zlecenia',error.message))},[orderId,loadedOrderId,p.status,workflow.suggestedStatus])
 const ensureNotes=async changes=>{const id=notes?.cloud_id||uid();await put('order_notes',id,{order_cloud_id:orderId,intake_notes:notes?.payload.intake_notes||'',qc_notes:notes?.payload.qc_notes||'',release_notes:notes?.payload.release_notes||'',...changes},{version:(notes?.version||0)+1});refresh()}
 const lookupOrderPart=async value=>{const code=normalizeBarcode(value||newPart.barcode);if(!isGtin(code))return Alert.alert('Kod produktu','Zeskanuj lub wpisz poprawny EAN, UPC albo GTIN.');partLookupRef.current=code;setPartLookupBusy(true);setPartLookupMessage('Sprawdzam magazyn i katalogi produktów…');try{const result=await findCatalogPart(code);setNewPart(orderPartDraft({...result.item,barcode:code}));setPartLookupMessage(result.message)}catch(error){setPartLookupMessage('Nie udało się wyszukać kodu. Możesz uzupełnić część ręcznie.');Alert.alert('Wyszukiwanie części',error.message)}finally{setPartLookupBusy(false)}}
 useEffect(()=>{const code=normalizeBarcode(newPart.barcode);if(!code){partLookupRef.current='';return}if(!isGtin(code)||partLookupRef.current===code)return;const timer=setTimeout(()=>lookupOrderPart(code),160);return()=>clearTimeout(timer)},[newPart.barcode])
 const chooseRepair=id=>{setSelectedRepairId(id);setCenterTab('parts')}
 const takeFromStock=async row=>{try{if(!selectedRepair)throw new Error('Najpierw wybierz pozycję naprawy.');await assignInventoryPart({inventoryId:row.cloud_id,orderId,repairItemId:selectedRepair.cloud_id,qty:wholePartQuantity(stockQty),vehicle:car});setStockQty('1');refresh()}catch(error){Alert.alert('Część z magazynu',error.message)}}
 const addPart=async()=>{try{if(!selectedRepair)throw new Error('Wybierz pozycję naprawy, do której należy część.');if(!newPart.name||!newPart.oe_number)throw new Error('Wpisz numer OE zweryfikowany dla wybranego pojazdu.');const qty=wholePartQuantity(newPart.qty),jobPartId=uid(),costItemId=uid(),source=partSource==='ZAMÓW CZĘŚĆ'?'ZAMOWIENIE':'RECZNIE',status=source==='ZAMOWIENIE'?'DO_ZAMOWIENIA':'ODEBRANE',relation={order_cloud_id:orderId,repair_item_cloud_id:selectedRepair.cloud_id,repair_name:selectedRepair.payload.name,source};await put('job_part_orders',jobPartId,{...relation,cost_item_cloud_id:costItemId,barcode:newPart.barcode,brand:newPart.brand,name:newPart.name,part_no:newPart.part_no,oe_number:newPart.oe_number,cross_numbers:newPart.cross_numbers,vehicle_fitment:newPart.vehicle_fitment,lookup_source:newPart.lookup_source,lookup_url:newPart.lookup_url,supplier_name:newPart.supplier,vehicle_snapshot:JSON.stringify({plate:car.plate||'',vin:car.vin||'',make:car.make||'',model:car.model||'',generation:car.generation||'',year:car.year||'',engine:car.engine||'',engine_code:car.engine_code||''}),qty,unit_cost:Number(newPart.unit_cost)||0,unit_price:Number(newPart.unit_price)||0,status,external_order_no:'',expected_at:null});await put('order_items',costItemId,{...relation,job_part_order_cloud_id:jobPartId,kind:'CZESC',name:newPart.name,brand:newPart.brand,part_no:newPart.part_no,qty,unit_cost:Number(newPart.unit_cost)||0,unit_price:Number(newPart.unit_price)||0});setNewPart(emptyOrderPart());setPartLookupMessage('');partLookupRef.current='';refresh()}catch(error){Alert.alert('Części',error.message)}}
