 if(!orders.length)return <Section title="Centrum zlecenia"><Text style={s.muted}>Brak zleceń.</Text></Section>
 if(!orderId||!o)return <Section title="Szybki podgląd zleceń"><Text style={s.desc}>Wybierz konkretne zlecenie, aby przejść do pracy i edycji.</Text><OrderPicker orders={orders} vehicles={vehicles} value="" onChange={setOrderId}/></Section>
 if(!sameRecordId(loadedOrderId,orderId))return <LoadingState label="Ładowanie zlecenia…"/>
