    <View style={ow.vehicleFacts}>{car.plate&&<Text style={ow.vehicleFact}>REJ. {car.plate}</Text>}{car.vin&&<Text style={ow.vehicleFact}>VIN {car.vin}</Text>}<StatusBadge value={p.status||'PRZYJETE'} label={String(p.status||'PRZYJETE').replaceAll('_',' ')}/></View>
