  {centerTab==='contact'&&<Section title="Kontakt z klientem"><View style={s.row}><View style={{flex:1}}><Text style={s.rowTitle}>{p.customer||'Klient nieprzypisany'}</Text><Text style={s.muted}>{p.phone||'Brak numeru telefonu'}{p.email?` · ${p.email}`:''}</Text></View><View style={s.inlineBtns}>{!!p.phone&&<Button small primary onPress={()=>Linking.openURL(`tel:${String(p.phone).replace(/[^+\d]/g,'')}`)}>Zadzwoń</Button>}{!!p.email&&<Button small onPress={()=>Linking.openURL(`mailto:${p.email}`)}>E-mail</Button>}</View></View><Text style={s.desc}>Historia wiadomości i ustaleń synchronizuje się z modułem Kontakt na PC.</Text></Section>}

