  {centerTab==='timeline'&&<RepairHistory orders={orders.map(row=>({...row,payload:{...row.payload,vehicle_cloud_id:resolveOrderVehicle(row.payload,vehicles).vehicle?.cloud_id||row.payload.vehicle_cloud_id}}))} vehicleId={vehicleId} items={allItems} onOpen={setOrderId} Section={Section}/>}
  {centerTab==='quote'&&<><MobileFinalPrice orderId={orderId} calculatedTotal={calculatedTotal} order={p} refresh={refresh}/><SettlementPanel orderId={orderId} total={total} paid={paid} approvals={approvals} qc={qc} diag={diag} parts={parts} items={items} order={p} vehicle={car} workflow={workflow} status={p.status||'PRZYJETE'} refresh={refresh}/></>}

