async function findCatalogPart(value){
 const code=normalizeBarcode(value)
 if(!isGtin(code))throw new Error('Kod nie jest poprawnym EAN, UPC ani GTIN.')
 const stock=await list('inventory_parts'),local=stock.find(row=>normalizeBarcode(row.payload.barcode)===code)
 if(local)return {found:true,item:{...local.payload,barcode:code},message:partLookupMessage(local.payload,true),fromStock:true}
 const cached=(await list('barcode_lookup_cache')).find(row=>row.cloud_id===code&&Date.parse(row.payload.expires_at)>Date.now())
 if(cached?.payload.status==='FOUND'&&cached.payload.item?.lookup_version===LOOKUP_VERSION)return {found:true,item:cached.payload.item,message:'Znaleziono dane w lokalnej pamięci kodów.',cached:true}
 const result=await lookupBarcodeOnline(code)
 if(result.found){await put('barcode_lookup_cache',code,{status:'FOUND',item:result.item,expires_at:new Date(Date.now()+180*86400000).toISOString()},{dirty:0});return {found:true,item:result.item,message:partLookupMessage(result.item)}}
 await put('barcode_lookup_cache',code,{status:'MISS',source:LOOKUP_VERSION,expires_at:new Date(Date.now()+86400000).toISOString()},{dirty:0})
 return {found:false,item:{barcode:code},message:result.unavailable?'Katalogi są chwilowo niedostępne. Dane można wpisać ręcznie.':'Nie znaleziono produktu. Wpisz dane części ręcznie.'}
}

