function Documents({tick}){
 const[busy,setBusy]=useState(''),[deliveries,setDeliveries]=useState([]),[query,setQuery]=useState(''),[expanded,setExpanded]=useState('')
 useEffect(()=>{list('delivery_document_imports').then(setDeliveries)},[tick])
 const open=async doc=>{try{setBusy(doc.title);const a=Asset.fromModule(doc.asset);await a.downloadAsync();if(!a.localUri)throw new Error('Nie udało się przygotować pliku PDF.');if(!(await Sharing.isAvailableAsync()))throw new Error('Android nie udostępnia aplikacji do otwarcia tego PDF.');await Sharing.shareAsync(a.localUri,{mimeType:'application/pdf',dialogTitle:`Otwórz ${doc.title}`})}catch(e){Alert.alert('Dokument PDF',e.message)}finally{setBusy('')}}
 const openScan=async row=>{const uri=row.payload.local_uri;if(!uri)return Alert.alert('Skan dostawy','Plik skanu jest na drugim urządzeniu. Uruchom synchronizację plików.');try{await Sharing.shareAsync(uri,{mimeType:row.payload.mime||'image/jpeg',dialogTitle:row.payload.document_no||'Skan dostawy'})}catch(error){Alert.alert('Skan dostawy',error.message)}}
 const shown=filterRecords(deliveries,query,row=>({...row.payload,items:JSON.stringify(row.payload.items||[])}))
 return <><Section title={`Archiwum skanów hurtowni · ${deliveries.length}`}><Text style={s.desc}>Dokumenty przyjęcia części, ich pozycje i wartości. Archiwum synchronizuje się z wersją PC.</Text><SearchBar value={query} onChange={setQuery} count={`${shown.length}/${deliveries.length}`} placeholder="Dostawca, numer dokumentu lub część"/>{shown.map(row=>{const p=row.payload,items=Array.isArray(p.items)?p.items:[],isOpen=expanded===row.cloud_id;return <View key={row.cloud_id} style={ix.deliveryCard}><Pressable onPress={()=>setExpanded(isOpen?'':row.cloud_id)} style={ix.deliveryHead}><View style={{flex:1}}><Text style={s.rowTitle}>{p.supplier_name||'Dostawca nieustalony'}</Text><Text style={s.muted}>{p.document_no||'bez numeru'} · {p.document_date||dt(row.updated_at)} · {items.length} poz.</Text></View><Text style={s.price}>{money(p.gross_total||p.document_gross_total)}</Text></Pressable>{isOpen&&<View style={ix.deliveryBody}>{items.map((item,index)=><View key={index} style={ix.deliveryItem}><View style={{flex:1}}><Text style={s.rowTitle}>{item.name||'Pozycja bez nazwy'}</Text><Text style={s.muted}>{item.part_no||item.catalog_no||'brak nr'} · {partQuantityLabel(item.quantity||item.qty||1)}</Text></View><Text style={s.price}>{money(item.gross_total||item.total_gross||item.price_gross)}</Text></View>)}<Button small onPress={()=>openScan(row)}>Otwórz skan</Button></View>}</View>})}{!shown.length&&<Text style={s.muted}>Brak zapisanych skanów dostaw.</Text>}</Section><Section title="Dokumenty Autologiki — offline"><Text style={s.desc}>Dokumenty PDF dołączone do aplikacji i dostępne bez Internetu.</Text>{OFFLINE_DOCS.map(d=><View key={d.title} style={s.row}><View style={{flex:1}}><Text style={s.rowTitle}>{d.title}</Text><Text style={s.muted}>{d.desc}</Text></View><Button small onPress={()=>open(d)} disabled={busy===d.title}>{busy===d.title?'…':'Otwórz PDF'}</Button></View>)}</Section></>
}
function AppUpdatePanel(){
 const currentVersion=Application.nativeApplicationVersion||APP_VERSION
 const[autoNotify,setAutoNotify]=useState(true)
 const[state,setState]=useState({phase:'idle',update:null,progress:0,fileUri:'',message:'Naciśnij przycisk, aby sprawdzić najnowsze wydanie.'})
 const check=async()=>{setState(value=>({...value,phase:'checking',message:'Łączę z serwerem aktualizacji…'}));try{const update=await fetchReleaseUpdate(currentVersion);setState({phase:update.available?'available':'latest',update,progress:0,fileUri:'',message:update.available?`Dostępna jest wersja ${update.version}.`:`Masz najnowszą wersję ${currentVersion}.`})}catch(error){setState(value=>({...value,phase:'error',message:error.message||'Nie udało się sprawdzić aktualizacji.'}))}}
 useEffect(()=>{check();metaGet('autoUpdateNotifications').then(value=>setAutoNotify(value!=='0')).catch(()=>{})},[])
 const download=async()=>{const update=state.update;if(!update?.downloadUrl)return;try{const directory=`${FileSystem.cacheDirectory}autologika-updates/`;await FileSystem.makeDirectoryAsync(directory,{intermediates:true});const fileUri=`${directory}Autologika-Android-${update.version}.apk`;await FileSystem.deleteAsync(fileUri,{idempotent:true});setState(value=>({...value,phase:'downloading',progress:0,message:'Pobieranie instalatora…'}));const task=FileSystem.createDownloadResumable(update.downloadUrl,fileUri,{},event=>{const total=Number(event.totalBytesExpectedToWrite||0),written=Number(event.totalBytesWritten||0);setState(value=>({...value,progress:total?written/total:0}))});const result=await task.downloadAsync();if(!result?.uri)throw new Error('Nie udało się zapisać pobranego instalatora.');const info=await FileSystem.getInfoAsync(result.uri);if(!info.exists||Number(info.size||0)<1000000)throw new Error('Pobrany plik APK jest niekompletny.');setState(value=>({...value,phase:'downloaded',progress:1,fileUri:result.uri,message:`Wersja ${update.version} jest gotowa do instalacji.`}))}catch(error){setState(value=>({...value,phase:'error',message:error.message||'Pobieranie aktualizacji nie powiodło się.'}))}}
 const permissions=()=>IntentLauncher.startActivityAsync('android.settings.MANAGE_UNKNOWN_APP_SOURCES',{data:`package:${Application.applicationId}`}).catch(()=>Linking.openSettings())
 const install=async()=>{if(!state.fileUri)return;try{const contentUri=await FileSystem.getContentUriAsync(state.fileUri);await IntentLauncher.startActivityAsync('android.intent.action.VIEW',{data:contentUri,type:'application/vnd.android.package-archive',flags:1})}catch(error){Alert.alert('Instalacja aktualizacji','Android może wymagać zezwolenia na instalowanie aplikacji z tego źródła.',[{text:'Anuluj',style:'cancel'},{text:'Otwórz ustawienia',onPress:permissions}])}}
 const busy=['checking','downloading'].includes(state.phase),notes=shortReleaseNotes(state.update?.notes)
 return <Section title="Aktualizacje aplikacji"><View style={s.row}><View style={{flex:1}}><Text style={s.rowTitle}>Powiadomienia o nowej wersji</Text><Text style={s.muted}>Sprawdzanie przy uruchomieniu i po powrocie do aplikacji, najwyżej co 6 godzin.</Text></View><Button primary={autoNotify} onPress={async()=>{try{const enabled=!autoNotify;await metaSet('autoUpdateNotifications',enabled?'1':'0');setAutoNotify(enabled)}catch(error){Alert.alert('Aktualizacje',error.message)}}}>{autoNotify?'WŁ.':'WYŁ.'}</Button></View><View style={up.hero}><View style={{flex:1}}><Text style={s.eyebrow}>AUTOLOGIKA ANDROID</Text><Text style={up.version}>Wersja {currentVersion}</Text><Text style={s.desc}>{state.message}</Text></View><Text style={[up.state,state.phase==='available'&&up.stateNew,state.phase==='latest'&&up.stateOk]}>{state.phase==='available'?'NOWA WERSJA':state.phase==='latest'?'AKTUALNA':state.phase==='downloading'?`${Math.round(state.progress*100)}%`:state.phase==='downloaded'?'GOTOWA':'SYSTEM'}</Text></View>{state.phase==='downloading'&&<View style={up.progress}><View style={[up.progressFill,{width:`${Math.max(2,state.progress*100)}%`}]}/></View>}{notes.length>0&&<View style={up.notes}>{notes.map((note,index)=><Text key={`${note}-${index}`} style={up.note}>• {note}</Text>)}</View>}<View style={s.inlineBtns}><Button primary={!busy&&state.phase!=='downloaded'} disabled={busy} onPress={state.phase==='available'?download:check}>{state.phase==='checking'?'Sprawdzam…':state.phase==='downloading'?`Pobieranie ${Math.round(state.progress*100)}%`:state.phase==='available'?'Pobierz aktualizację':state.phase==='downloaded'?'Pobrano':'Sprawdź aktualizacje'}</Button>{state.phase==='downloaded'&&<Button primary onPress={install}>Zainstaluj wersję {state.update?.version}</Button>}{state.update?.pageUrl&&<Button onPress={()=>Linking.openURL(state.update.pageUrl)}>Informacje o wersji</Button>}{state.phase==='error'&&<Button onPress={check}>Spróbuj ponownie</Button>}</View><Text style={s.muted}>Po pobraniu Android pokaże systemowe potwierdzenie instalacji. Dane warsztatu pozostają w lokalnej bazie aplikacji.</Text></Section>
}function WorkshopSettingsSection(){
 const[layout,setLayout]=useState(DEFAULT_WORKSHOP_LAYOUT),[record,setRecord]=useState(null),[saved,setSaved]=useState('')
 const load=()=>list('app_settings').then(rows=>{setLayout(workshopLayoutFromRows(rows));setRecord(rows.find(row=>row.cloud_id===WORKSHOP_LAYOUT_ID||row.payload?.setting_key==='workshop_layout_v1')||null)})
 useEffect(()=>{load()},[])
 const resize=value=>{const count=Math.max(1,Math.min(20,Math.round(Number(value)||1)));setLayout(current=>({...current,bays:Array.from({length:count},(_,index)=>current.bays[index]||`Stanowisko ${index+1}`)}))}
 const rename=(index,value)=>setLayout(current=>({...current,bays:current.bays.map((name,i)=>i===index?value:name)}))
 const save=async()=>{try{const normalized=normalizeWorkshopLayout(layout);await put('app_settings',WORKSHOP_LAYOUT_ID,workshopLayoutPayload(normalized),{version:(record?.version||0)+1});setLayout(normalized);setSaved('Zapisano. Terminarz użyje nowej konfiguracji.');await load();setTimeout(()=>setSaved(''),3000)}catch(error){Alert.alert('Organizacja warsztatu',error.message)}}
 return <Section title="Organizacja warsztatu"><Text style={s.desc}>Ustaw liczbę i nazwy stanowisk, godziny pracy oraz standardową długość nowej wizyty. Konfiguracja synchronizuje się z wersją PC.</Text><View style={s.form2}><Field label="Liczba stanowisk" value={layout.bays.length} onChangeText={resize} keyboardType="numeric"/><Field label="Domyślna wizyta [min]" value={layout.defaultAppointmentMinutes} onChangeText={value=>setLayout({...layout,defaultAppointmentMinutes:Number(value)||60})} keyboardType="numeric"/><Field label="Otwarcie [godz.]" value={layout.openingHour} onChangeText={value=>setLayout({...layout,openingHour:Number(value)})} keyboardType="numeric"/><Field label="Zamknięcie [godz.]" value={layout.closingHour} onChangeText={value=>setLayout({...layout,closingHour:Number(value)})} keyboardType="numeric"/></View><Text style={s.label}>Nazwy stanowisk</Text><View style={{gap:8,marginBottom:12}}>{layout.bays.map((name,index)=><View key={index} style={s.row}><Text style={s.badge}>{String(index+1).padStart(2,'0')}</Text><View style={{flex:1}}><Field label={`Stanowisko ${index+1}`} value={name} onChangeText={value=>rename(index,value)}/></View></View>)}</View><View style={s.inlineBtns}><Button primary onPress={save}>Zapisz organizację warsztatu</Button></View>{!!saved&&<Text style={s.ok}>{saved}</Text>}</Section>
}
function Settings({sync,syncing}){const[c,setC]=useState({url:'',key:'',deviceId:`android-${Date.now()}`,workshopId:'',autoSync:true}),[savedKey,setSavedKey]=useState({configured:false,hint:'',length:0,kind:'empty'}),[msg,setMsg]=useState(''),[testMsg,setTestMsg]=useState(''),[auth,setAuth]=useState({email:'',password:''}),[account,setAccount]=useState({});const reload=()=>Promise.all([currentAccount(),publicCloudConfig()]).then(([a,p])=>{setAccount(a);setSavedKey({configured:p.keyConfigured,hint:p.keyHint,length:p.keyLength,kind:p.keyKind});setC(v=>({...v,url:p.url||v.url,key:'',deviceId:p.deviceId||v.deviceId,workshopId:p.workshopId??v.workshopId,autoSync:p.autoSync??v.autoSync}))}).catch(()=>{});useEffect(()=>{reload()},[]);const save=async()=>{try{await saveCloud(c);setMsg('Konfiguracja zapisana na tablecie.');setC(x=>({...x,key:''}));reload()}catch(e){Alert.alert('Konfiguracja',e.message)}};const test=async()=>{try{await saveCloud(c);const r=await testConnection();setTestMsg(`Połączenie OK · HTTP ${r.status}`);setC(x=>({...x,key:''}));reload()}catch(e){setTestMsg(`Błąd: ${e.message}`)}};const signIn=async()=>{try{await saveCloud(c);await login(auth.email,auth.password);setMsg('Zalogowano do Autologika Cloud.');setC(x=>({...x,key:''}));reload()}catch(e){Alert.alert('Logowanie',e.message)}};const signUp=async()=>{try{await saveCloud(c);await signup(auth.email,auth.password);setMsg('Konto utworzone. Jeśli Supabase wymaga potwierdzenia e-mail, potwierdź wiadomość i zaloguj się.');setC(x=>({...x,key:''}));reload()}catch(e){Alert.alert('Rejestracja',e.message)}};return <><AppUpdatePanel/><WorkshopSettingsSection/><Section title="Autologika Cloud — bezpieczne konto"><Text style={s.desc}>Synchronizacja używa konta użytkownika i tokenu sesji. Wpisuj wyłącznie Publishable key (sb_publishable_...) lub starszy anon key. Klucz sb_secret_ jest blokowany.</Text><Field label="Supabase URL" value={c.url} onChangeText={x=>setC({...c,url:x})} placeholder="https://...supabase.co"/><Field label="Publishable key" value={c.key} onChangeText={x=>setC({...c,key:x})} placeholder={savedKey.configured?'pozostaw puste, aby zachować zapisany klucz':'sb_publishable_...'}/>{savedKey.configured&&<Text style={s.muted}>Zapisany klucz: {savedKey.hint} · {savedKey.length} znaków · {savedKey.kind}</Text>}<Field label="ID urządzenia" value={c.deviceId} onChangeText={x=>setC({...c,deviceId:x})}/><Field label="ID warsztatu z konta Cloud" value={account.loggedIn?account.userId:'Po zalogowaniu'} editable={false}/><View style={s.inlineBtns}><Button primary onPress={save}>Zapisz konfigurację</Button><Button onPress={test}>Test połączenia</Button><Button disabled={syncing||!account.loggedIn} onPress={()=>sync(false)}>Synchronizuj teraz</Button><Button disabled={syncing||!account.loggedIn} onPress={()=>sync(false,true)}>Pełna synchronizacja</Button></View>{!!testMsg&&<Text style={testMsg.startsWith('Połączenie')?s.ok:s.warn}>{testMsg}</Text>}</Section><Section title="Konto"><View style={s.row}><View><Text style={s.rowTitle}>{account.loggedIn?account.email||'Zalogowano':'Brak aktywnej sesji'}</Text><Text style={s.muted}>{account.loggedIn?`użytkownik ${account.userId}`:'zaloguj się, aby uruchomić chmurę'}</Text>{account.loggedIn&&<Text style={s.muted}>Na komputerze i Androidzie musi być zalogowane to samo konto.</Text>}</View><Text style={s.badge}>{account.loggedIn?'ONLINE':'OFFLINE'}</Text></View>{!account.loggedIn?<><Field label="E-mail" value={auth.email} onChangeText={x=>setAuth({...auth,email:x})}/><Field label="Hasło" value={auth.password} onChangeText={x=>setAuth({...auth,password:x})}/><View style={s.inlineBtns}><Button primary onPress={signIn}>Zaloguj</Button><Button onPress={signUp}>Utwórz konto</Button></View></>:<Button danger onPress={async()=>{await logout();reload()}}>Wyloguj</Button>}{!!msg&&<Text style={s.ok}>{msg}</Text>}</Section><Section title="Kopia lokalna"><Text style={s.desc}>Eksportuje bieżący stan lokalnej bazy do pliku JSON. To awaryjna kopia urządzenia; główną ochroną danych pozostaje synchronizacja rekordowa z chmurą.</Text><Button onPress={async()=>{try{const f=await exportSnapshot();if(await Sharing.isAvailableAsync())await Sharing.shareAsync(f,{mimeType:'application/json',dialogTitle:'Kopia Autologika Android'});else Alert.alert('Kopia lokalna',f)}catch(e){Alert.alert('Kopia lokalna',e.message)}}}>Eksportuj kopię JSON</Button></Section><Section title="Tryb pracy"><View style={s.row}><Text style={s.rowTitle}>Offline-first</Text><Text style={s.badge}>AKTYWNY</Text></View><View style={s.row}><View><Text style={s.rowTitle}>Automatyczna synchronizacja</Text><Text style={s.muted}>co około 30 sekund, gdy aplikacja działa</Text></View><Button primary={!!c.autoSync} onPress={async()=>{const n={...c,autoSync:!c.autoSync};setC(n);await saveCloud(n)}}>{c.autoSync?'WŁ.':'WYŁ.'}</Button></View></Section></>}
function VinScanner({visible,onClose,onData}){
 const[permission,requestPermission]=useCameraPermissions(),[locked,setLocked]=useState(false),[last,setLast]=useState(null)
 useEffect(()=>{if(visible&&!permission?.granted)requestPermission()},[visible])
 const accept=async(data,source='CAMERA',format='')=>{if(locked)return;const raw=String(data||'').replace(/[\r\n]+$/,'');if(!raw)return;setLocked(true);const vin=(raw.toUpperCase().match(/\b[A-HJ-NPR-Z0-9]{17}\b/)||[])[0]||'';const capture={source,format,raw,length:raw.length,vin,captured_at:new Date().toISOString()};try{if(vin){capture.decoded=true;onData({form:{vin}})}else{const registration=decodeRegistration(raw);capture.decoded=true;capture.registration=registration;onData(registration)}}catch(error){capture.decode_error=error.message;Alert.alert('AZTEC zapisany',`Odebrano ${raw.length} znaków, ale dekoder nie rozpoznał dowodu: ${error.message}`)}finally{setLast(capture);await put('scanner_captures',uid(),capture);setTimeout(()=>setLocked(false),800)}}
 const hit=event=>accept(event.data,'CAMERA',event.type||'')
 return <Modal visible={visible} animationType="slide" onRequestClose={onClose}><SafeAreaView style={s.scannerRoot}><View style={s.scannerHead}><Text style={s.h1}>VIN / AZTEC</Text><Button onPress={onClose}>Zamknij</Button></View>{permission?.granted?<CameraView style={s.camera} onBarcodeScanned={locked?undefined:hit} barcodeScannerSettings={{barcodeTypes:['aztec','pdf417','qr','code128','code39']}}/>:<View style={s.panel}><Text style={s.muted}>Aplikacja potrzebuje dostępu do aparatu.</Text><Button primary onPress={requestPermission}>Nadaj dostęp</Button></View>}{last?<View style={s.scanMobileResult}><Text style={s.badge}>{last.source} · {last.format||'RAW'}</Text><Text style={s.rowTitle}>{last.vin||`${last.length} znaków zapisanych`}</Text></View>:null}<Text style={s.desc}>VIN jest od razu przekazywany do przyjęcia. Każdy nierozpoznany payload AZTEC zapisujemy lokalnie, aby na prawdziwym skanie z dowodu dopracować dekoder bez utraty danych.</Text></SafeAreaView></Modal>
}

function MediaPanel({orderId,media,refresh}){const[categ,setCateg]=useState('PRZYJECIE');useEffect(()=>{syncNow().then(refresh).catch(()=>{})},[orderId]);const categories=['PRZYJECIE','DIAGNOZA','NAPRAWA','WYDANIE'];const shown=media.filter(x=>(x.payload.category||'PRZYJECIE')===categ);const add=async(camera)=>{const perm=camera?await ImagePicker.requestCameraPermissionsAsync():await ImagePicker.requestMediaLibraryPermissionsAsync();if(!perm.granted)return Alert.alert('Zdjęcia','Brak uprawnień.');const r=camera?await ImagePicker.launchCameraAsync({mediaTypes:['images'],quality:.8}):await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],quality:.8,allowsMultipleSelection:true});if(r.canceled)return;const dir=`${FileSystem.documentDirectory}autologika/captured/`;await FileSystem.makeDirectoryAsync(dir,{intermediates:true});for(const a of r.assets||[]){const id=uid();const ext=(a.fileName?.match(/\.[a-zA-Z0-9]{1,8}$/)||[(a.mimeType==='image/png'?'.png':'.jpg')])[0];const local=`${dir}${id}${ext}`;try{await FileSystem.copyAsync({from:a.uri,to:local})}catch{}await put('attachments',id,{order_cloud_id:orderId,name:a.fileName||`zdjecie-${Date.now()}${ext}`,mime:a.mimeType||'image/jpeg',local_uri:local,width:a.width,height:a.height,category:categ,created_at:new Date().toISOString(),storage_path:''})}refresh();syncNow().then(refresh).catch(()=>{})};const del=x=>Alert.alert('Usuń załącznik',`Usunąć ${x.payload.name||'plik'} z tego zlecenia?`,[{text:'Anuluj',style:'cancel'},{text:'Usuń',style:'destructive',onPress:async()=>{try{if(x.payload.local_uri)await FileSystem.deleteAsync(x.payload.local_uri,{idempotent:true})}catch{}await remove('attachments',x.cloud_id);refresh()}}]);return <Section title="Dokumentacja zdjęciowa" action={<View style={s.inlineBtns}><Button small onPress={()=>syncNow().then(refresh).catch(error=>Alert.alert('Synchronizacja dokumentacji',error.message))}>↻ Synchronizuj</Button><Button small primary onPress={()=>add(true)}>📷 Aparat</Button><Button small onPress={()=>add(false)}>Galeria</Button></View>}><PillRow items={categories} value={categ} onChange={setCateg}/><Text style={s.desc}>Zdjęcia są porządkowane etapami: przyjęcie, diagnoza, naprawa i wydanie. Usunięcie zapisuje tombstone i po synchronizacji usuwa rekord również z drugiego urządzenia.</Text><ScrollView horizontal contentContainerStyle={s.mediaStrip}>{shown.map(x=><View key={x.cloud_id} style={s.mediaCard}>{x.payload.local_uri?<Image source={{uri:x.payload.local_uri}} style={s.thumb}/>:<View style={s.thumb}/>}<Text style={s.muted} numberOfLines={1}>{x.payload.name||'zdjęcie'}</Text><View style={s.inlineBtns}><Text style={s.badge}>{x.dirty?'DO SYNC':x.payload.storage_path?'CHMURA':'LOKALNIE'}</Text><Button small danger onPress={()=>del(x)}>×</Button></View></View>)}</ScrollView>{!shown.length&&<Text style={s.muted}>Brak zdjęć w kategorii {categ.replaceAll('_',' ').toLowerCase()}.</Text>}</Section>}
function SignaturePanel({orderId,signatures,refresh}){const[points,setPoints]=useState([]),[name,setName]=useState('');const ref=useRef([]);const pan=useMemo(()=>PanResponder.create({onStartShouldSetPanResponder:()=>true,onMoveShouldSetPanResponder:()=>true,onPanResponderGrant:e=>{ref.current=[[e.nativeEvent.locationX,e.nativeEvent.locationY]];setPoints([...ref.current])},onPanResponderMove:e=>{ref.current=[...ref.current,[e.nativeEvent.locationX,e.nativeEvent.locationY]];setPoints([...ref.current])}}),[]);const save=async()=>{if(points.length<4)return Alert.alert('Podpis','Złóż podpis w polu.');await put('signatures',uid(),{order_cloud_id:orderId,signed_by:name||'Klient',points,created_at:new Date().toISOString()});setPoints([]);setName('');refresh()};return <Section title="Podpis klienta"><Field label="Imię / podpisujący" value={name} onChangeText={setName} placeholder="Klient"/><View style={s.signature} {...pan.panHandlers}><Svg width="100%" height="100%"><Polyline points={points.map(p=>p.join(',')).join(' ')} fill="none" stroke="#e7edf2" strokeWidth="2.5"/></Svg></View><View style={s.inlineBtns}><Button onPress={()=>setPoints([])}>Wyczyść</Button><Button primary onPress={save}>Zapisz podpis</Button></View>{signatures.slice(0,3).map(x=><View key={x.cloud_id} style={s.row}><Text style={s.rowTitle}>{x.payload.signed_by||'Klient'}</Text><Text style={s.muted}>{dt(x.payload.created_at)}</Text></View>)}</Section>}


